CREATE TABLE member_sms_challenge(mobile VARCHAR(24) NOT NULL COMMENT '手机号码',scene VARCHAR(40) NOT NULL COMMENT '验证码业务场景',code_hash VARCHAR(64) NULL COMMENT '短信验证码摘要',expires_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '到期时间',attempts INT NOT NULL DEFAULT 0 COMMENT '已尝试校验次数',last_sent_at DATETIME NULL COMMENT '最近短信发送时间',sent_date DATE NULL COMMENT '短信发送计数日期',daily_count INT NOT NULL DEFAULT 0 COMMENT '当日短信发送次数',PRIMARY KEY(mobile,scene)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员短信验证码校验状态';
CREATE TABLE member_sms_budget(budget_day DATE PRIMARY KEY COMMENT '短信总预算日期',requests INT NOT NULL DEFAULT 0 COMMENT '当日短信请求总数') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员短信日请求预算';
CREATE TABLE member_social_state(state_hash VARCHAR(64) PRIMARY KEY COMMENT '第三方授权状态摘要',provider VARCHAR(100) NOT NULL COMMENT '第三方身份提供方',purpose VARCHAR(16) NOT NULL COMMENT '第三方授权用途',member_id BIGINT NULL COMMENT '会员编号',expires_at DATETIME NOT NULL COMMENT '到期时间') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员第三方授权状态';
CREATE TABLE member_social_binding(provider VARCHAR(100) NOT NULL COMMENT '第三方身份提供方',subject VARCHAR(200) NOT NULL COMMENT '第三方用户唯一标识',member_id BIGINT NOT NULL COMMENT '会员编号',PRIMARY KEY(provider,subject),UNIQUE KEY uk_member_provider(member_id,provider),FOREIGN KEY(member_id) REFERENCES member_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员第三方身份绑定';
